<script setup lang="ts">import{ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{treeApi}from'../api/tree';import PageHeader from'../components/PageHeader.vue';const path=ref(''),name=ref(''),isDir=ref(true),rows=ref<any[]>([]),loading=ref(false),walk=ref('层序遍历');async function load(){loading.value=true;try{const r:any=await treeApi.get({path:path.value});rows.value=Array.isArray(r.data)?r.data:(r.data?.children||r.data?.nodes||[])}finally{loading.value=false}}async function create(){if(!name.value.trim())return ElMessage.warning('请输入名称');await treeApi.create({parentPath:path.value,name:name.value.trim(),isDir:isDir.value});name.value='';ElMessage.success('创建成功');load()}async function remove(r:any){await ElMessageBox.confirm(`确定删除 ${r.name||r.path}？`,'二次确认');await treeApi.remove({path:r.path,confirm:true});ElMessage.success('已删除');load()}async function traverse(){const r:any=await treeApi.traverse({path:path.value,order:walk.value});rows.value=Array.isArray(r.data)?r.data:[]}</script>
<template><PageHeader title="文件目录" description="浏览并管理当前会话关联的目录树"><button class="btn secondary" @click="load">↻ 刷新</button></PageHeader><div class="card toolbar" style="margin-bottom:16px"><input v-model="path" class="field" style="flex:1" placeholder="目录路径 / 根目录"><button class="btn" @click="load">打开目录</button><select v-model="walk" class="field"><option>层序遍历</option><option>前序遍历</option><option>后序遍历</option></select><button class="btn secondary" @click="traverse">遍历</button><button class="btn secondary" @click="treeApi.undo().then(()=>{ElMessage.success('已撤销');load()})">撤销上一步</button></div><div class="grid grid-2"><div class="card"><h3 class="card-title">目录内容 <span class="muted">{{rows.length}} 项</span></h3><div v-if="loading" class="empty">正在读取目录…</div><div v-else class="table-wrap"><table><thead><tr><th>名称</th><th>类型</th><th>路径</th><th></th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td>{{r.name||r.path}}</td><td>{{r.isDir?'文件夹':'文件'}}</td><td>{{r.path||'—'}}</td><td><button class="btn danger" @click="remove(r)">删除</button></td></tr><tr v-if="!rows.length"><td colspan="4" class="empty">输入目录路径并打开，查看节点</td></tr></tbody></table></div></div><div class="card"><h3 class="card-title">新建节点</h3><div class="form-row"><label>父目录</label><input v-model="path" class="field" style="width:100%" placeholder="/path/to/folder"></div><div class="form-row"><label>名称</label><input v-model="name" class="field" style="width:100%" placeholder="例如：项目资料"></div><div class="form-row"><label>节点类型</label><select v-model="isDir" class="field" style="width:100%"><option :value="true">文件夹</option><option :value="false">文件</option></select></div><button class="btn" @click="create">创建节点</button></div></div></template>
